-- ==============================================================================
-- 06: a map pin and a place name on every itinerary day. Run after 05_experiences.sql. Safe to re-run.
-- Only fills days that have never had a pin, so pins the owner has moved or removed are kept.
-- Coordinates are approximate; generated by scripts/generate-phase-sql.mjs from lib/data/route-pins.js.
-- ==============================================================================

with pins (slug, day, place, lat, lng) as (
  values
    ('sandakphu-vintage-land-rover', 1, 'Tumling', 27.0313, 88.069),
    ('sandakphu-vintage-land-rover', 2, 'Kalipokhri', 27.079, 88.02),
    ('sandakphu-vintage-land-rover', 3, 'Sandakphu', 27.1048, 88.0015),
    ('sandakphu-vintage-land-rover', 4, 'Phalut', 27.2132, 88.0137),
    ('sandakphu-vintage-land-rover', 5, 'Darjeeling', 27.0378, 88.2632),
    ('sandakphu-vintage-land-rover', 6, 'New Jalpaiguri (NJP)', 26.6829, 88.4425),
    ('singalila-ridge-trek', 1, 'Chitrey', 27.015, 88.088),
    ('singalila-ridge-trek', 2, 'Tumling', 27.0313, 88.069),
    ('singalila-ridge-trek', 3, 'Kalipokhri', 27.079, 88.02),
    ('singalila-ridge-trek', 4, 'Sandakphu', 27.1048, 88.0015),
    ('singalila-ridge-trek', 5, 'Gurdum', 27.1215, 88.0567),
    ('singalila-ridge-trek', 6, 'Darjeeling', 27.0378, 88.2632),
    ('singalila-ridge-trek', 7, 'Bagdogra Airport', 26.6818, 88.3301),
    ('darjeeling-colonial-tea-retreat', 1, 'Makaibari, Kurseong', 26.866, 88.272),
    ('darjeeling-colonial-tea-retreat', 2, 'Makaibari, Kurseong', 26.866, 88.272),
    ('darjeeling-colonial-tea-retreat', 3, 'Darjeeling', 27.0378, 88.2632),
    ('darjeeling-colonial-tea-retreat', 4, 'Tiger Hill', 26.9949, 88.2853),
    ('darjeeling-colonial-tea-retreat', 5, 'Mirik Lake', 26.8899, 88.1826),
    ('offbeat-silk-route-zuluk', 1, 'Reshikhola', 27.1618, 88.6526),
    ('offbeat-silk-route-zuluk', 2, 'Zuluk', 27.2526, 88.7773),
    ('offbeat-silk-route-zuluk', 3, 'Gnathang Valley', 27.299, 88.8178),
    ('offbeat-silk-route-zuluk', 4, 'Aritar, Lampokhari Lake', 27.1867, 88.6766),
    ('offbeat-silk-route-zuluk', 5, 'New Jalpaiguri (NJP)', 26.6829, 88.4425),
    ('north-sikkim-gurudongmar-yumthang', 1, 'Gangtok', 27.329, 88.6123),
    ('north-sikkim-gurudongmar-yumthang', 2, 'Lachen', 27.7306, 88.5495),
    ('north-sikkim-gurudongmar-yumthang', 3, 'Gurudongmar Lake', 28.0271, 88.7107),
    ('north-sikkim-gurudongmar-yumthang', 4, 'Yumthang Valley', 27.8043, 88.7033),
    ('north-sikkim-gurudongmar-yumthang', 5, 'Gangtok', 27.329, 88.6123),
    ('north-sikkim-gurudongmar-yumthang', 6, 'New Jalpaiguri (NJP)', 26.6829, 88.4425),
    ('dooars-wildlife-rhino-safari', 1, 'Lataguri, Gorumara', 26.7065, 88.769),
    ('dooars-wildlife-rhino-safari', 2, 'Madarihat, Jaldapara', 26.7198, 89.1853),
    ('dooars-wildlife-rhino-safari', 3, 'Jaldapara National Park', 26.69, 89.29),
    ('dooars-wildlife-rhino-safari', 4, 'Jayanti, Buxa', 26.6754, 89.6377),
    ('dooars-wildlife-rhino-safari', 5, 'Hasimara', 26.727, 89.3473)
)
update public.packages p
set itinerary = (
  select coalesce(jsonb_agg(
    case
      when e.d ? 'pin' or x.slug is null then e.d
      else e.d || jsonb_build_object('place', coalesce(nullif(e.d->>'place', ''), x.place), 'pin', jsonb_build_object('lat', x.lat, 'lng', x.lng))
    end
    order by e.ord
  ), '[]'::jsonb)
  from jsonb_array_elements(p.itinerary) with ordinality as e(d, ord)
  left join pins x
    on x.slug = p.slug
   and x.day = case when e.d->>'day' ~ '^[0-9]+$' then (e.d->>'day')::int else e.ord::int end
)
where p.slug in (select distinct slug from pins)
  and jsonb_typeof(p.itinerary) = 'array'
  and jsonb_array_length(p.itinerary) > 0;
